SELECT 'gongkao', '并列关系', 'kp-xc-analogy-ext-parallel', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"并列关系"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"两个词同属一个大类，互不包含。如「苹果:香蕉」都是水果，「医生:教师」都是职业。约 472 题。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、题型识别"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"两个词是同一层级的不同事物"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"可以用「A 和 B 都是 X」造句"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、二级辨析"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"同一领域 vs 不同领域（如「苹果:香蕉」同属水果）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"矛盾关系 vs 反对关系（如「生:死」是矛盾，「红:蓝」是反对）"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"并列关系是高频考点（472 题），关键是找到「共同的上位概念」。当多个选项都是并列时，用二级辨析区分。"}]}]}]}$$ AS jsonb), NULL, '类比推理-外延关系-并列关系：同属一个大类的两个不同事物。', category_node.id, CAST('["类比推理", "外延关系", "并列关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_logical_parallel", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
